        host.wind_model_name = [weak]() -> std::string {
            const auto state = weak.lock();
            if (!state)
                return {};
            std::lock_guard lock(state->wind_config_mutex);
            using Model = RegionPolicies::Wind::Model;
            switch (state->policies.wind.model) {
            case Model::SimpleRandom:
                return "SimpleRandomWind";
            case Model::Configurable:
                return "ConfigurableWind";
            case Model::Disabled:
                return {};
            }
            return {};
        };
        host.wind_parameter = [weak](std::string_view plugin, std::string_view parameter, std::optional<float> update) {
            const auto state = weak.lock();
            if (!state)
                return 0.f;
            std::lock_guard lock(state->wind_config_mutex);
            auto &wind = state->policies.wind;
            if (wind.model == RegionPolicies::Wind::Model::Disabled)
                return 0.f;
            if (auto *value = wind_parameter(wind, plugin, parameter)) {
                if (update)
                    *value = *update;
                return *value;
            }
            if (update)
                return 0.f;
            if (plugin != "SimpleRandomWind" && plugin != "ConfigurableWind")
                throw std::runtime_error("Could not find plugin " + std::string(plugin));
            throw std::runtime_error("Unknown " + std::string(plugin) + " parameter " + std::string(parameter));
        };
