                    switch (selector) {
                    case 0:
                        return part->base_mask;
                    case 1:
                        return part->owner_mask;
                    case 2:
                        return part->group_mask;
                    case 3:
                        return part->everyone_mask;
                    case 4:
                        return part->next_mask;
                    }
