                    if (message.recipient != a.circuit->agent_id)
                        continue;
                    constexpr std::uint8_t inventory_offered = 4;
                    if (message.dialog != inventory_offered)
                        message.offline = 1;
                    deliver_instant_message(message, a.circuit->session_id);
