void RegionRuntime::export_world_map(const std::filesystem::path &path) const {
    const auto &policies = state_->policies;
    const auto region = descriptor();
    const auto distance = policies.map_export_view_distance;
    const auto min_x = std::int64_t(region.x) - distance;
    const auto min_y = std::int64_t(region.y) - distance;
    const auto max_x = std::int64_t(region.x) + region.size_x + distance;
    const auto max_y = std::int64_t(region.y) + region.size_y + distance;
    const auto width = max_x - min_x + 2;
    const auto height = max_y - min_y + 2;
    if (width <= 0 || height <= 0 || width > 65500 || height > 65500 ||
        width * height > std::numeric_limits<std::int32_t>::max() / 3 || min_x < std::numeric_limits<int>::min() ||
        min_y < std::numeric_limits<int>::min() || max_x > std::numeric_limits<int>::max() ||
        max_y > std::numeric_limits<int>::max())
        throw std::runtime_error("Invalid world map export dimensions");

    MapBitmap canvas{static_cast<std::uint32_t>(width), static_cast<std::uint32_t>(height),
                     std::vector<std::uint8_t>(static_cast<std::size_t>(width * height) * 3)};
    for (std::size_t pixel = 2; pixel < canvas.pixels.size(); pixel += 3)
        canvas.pixels[pixel] = 139; // DarkBlue
    const auto draw = [&](const services::GridRegion &tile, MapBitmap bitmap) {
        if (tile.size_x <= 0 || tile.size_y <= 0 ||
            std::int64_t(tile.size_x) * tile.size_y > std::numeric_limits<std::int32_t>::max() / 4)
            return;
        const auto x = std::int64_t(tile.x) - min_x + 1;
        const auto y = height - (std::int64_t(tile.y) - min_y + 1) - tile.size_y;
        composite_map_bitmap(canvas, std::move(bitmap), x, y, tile.size_x, tile.size_y);
    };

    const auto filename = policies.map_tiles_directory / ("MAP-" + region.id.str() + ".png");
    draw(region, load_static_map_bitmap(filename));
    if (policies.map_export_region_name && region.name) {
        const auto x = std::int64_t(region.x) - min_x + 31;
        const auto y = height - (std::int64_t(region.y) - min_y + 31);
        draw_map_label(canvas, *region.name, x, y, true);
    }
    if (policies.map_region_range && policies.load_map_asset) {
        const auto neighbors = policies.map_region_range(static_cast<int>(min_x), static_cast<int>(max_x),
                                                         static_cast<int>(min_y), static_cast<int>(max_y));
        for (const auto &neighbor : neighbors) {
            if ((neighbor.x == region.x && neighbor.y == region.y) || neighbor.terrain_image.is_zero())
                continue;
            draw(neighbor, policies.load_map_asset(neighbor.terrain_image));
        }
    }

    if (policies.map_export_scale)
        draw_map_label(canvas, std::to_string(width) + "m x " + std::to_string(height) + "m", 30, 30, false);

    const auto jpeg = encode_map_bitmap_jpeg(canvas);
    if (jpeg.empty())
        throw std::runtime_error("Could not encode the exported world map");
    std::ofstream output(path, std::ios::binary | std::ios::trunc);
    if (!output.write(jpeg.data(), static_cast<std::streamsize>(jpeg.size())))
        throw std::runtime_error("Could not write the exported world map");
}

void RegionRuntime::poll(double host_sleep_ms) {
    auto &state = *state_;
    if (!state.running)
        return;
    state.restore_keyframed_motions();
    ++state.script_region_frame;
    state.report_stats(host_sleep_ms);
    state.poll_estate_region_change();
    state.poll_estate_restart();
    state.poll_environment_time();
    state.poll_map_tile_refresh();
    {
        std::lock_guard lock(state.new_mutex);
        const auto now = std::chrono::steady_clock::now();
        std::erase_if(state.incoming_attachments, [](const auto &entry) { return entry.first.expired(); });
        std::erase_if(state.incoming_object_attachments, [](const auto &entry) { return entry.first.expired(); });
        std::erase_if(state.incoming_teleports, [&](const auto &entry) {
            const auto &circuit = entry.first;
            if (state.circuits.get_agent_circuit_data(circuit->circuit_code) != circuit) {
                state.discard_incoming_transfer(circuit);
                return true;
            }
            const auto viewer = state.viewers->agent(circuit->agent_id);
            if (viewer && viewer->circuit == circuit && viewer->root)
                return true;
            if (entry.second > now)
                return false;
            if (viewer && viewer->crossed_child && viewer->circuit->session_id == circuit->session_id &&
                (viewer->circuit != circuit || viewer->retained_crossing_circuit)) {
                state.cancel_retained_crossing(circuit);
                return true;
            }
            if (viewer && viewer->circuit == circuit &&
                state.viewers->transport().remove_client_if_session(circuit->agent_id, circuit->session_id))
                return true;
            const bool current = state.circuits.remove_current_circuit(circuit);
            state.discard_incoming_transfer(circuit);
            if (state.capability_runtime) {
                if (current)
                    state.capability_runtime->client_closed(circuit->agent_id);
                state.capability_runtime->capabilities().remove_circuit_caps(*circuit, current);
            }
            return true;
        });
    }
    {
        std::vector<State::PendingTeleport> arrived, expired, aborted, cancelled;
        std::vector<State::TransferIdentity> superseded;
        {
            std::lock_guard lock(state.teleport_mutex);
            const auto now = std::chrono::steady_clock::now();
            std::erase_if(state.transfer_workers, [](const auto &waiting) {
                return waiting.wait_for(std::chrono::seconds(0)) == std::future_status::ready;
            });
            std::erase_if(state.pending_teleports, [&](const auto &transfer) {
                if (!state.owns_transfer_locked({transfer.agent, transfer.session, transfer.generation, {}}))
                    return true;
                const auto current = state.viewers->agent(transfer.agent);
                if (transfer.source_circuit && current && current->root && !current->logout_requested &&
                    current->circuit != transfer.source_circuit) {
                    superseded.push_back({transfer.agent, transfer.session, transfer.generation, {}});
                    return true;
                }
                bool legacy_success = false, legacy_error = false;
                if (transfer.legacy_protocol && !transfer.update_wait.valid()) {
                    if (!transfer.arrival_wait.valid() ||
                        transfer.arrival_wait.wait_for(std::chrono::seconds(0)) != std::future_status::ready)
                        return false;
                    try {
                        legacy_success = transfer.arrival_wait.get();
                    } catch (...) {
                        legacy_error = true;
                    }
                }
                if (transfer.update_wait.valid()) {
                    if (transfer.update_wait.wait_for(std::chrono::seconds(0)) != std::future_status::ready)
                        return false;
                    bool success = false;
                    try {
                        success = transfer.update_wait.get();
                    } catch (...) {
                    }
                    if (success) {
                        if (transfer.legacy_protocol)
                            state.transfer_states.update_in_transit(transfer.agent, AgentTransferState::CleaningUp);
                        arrived.push_back(transfer);
                    } else if (state.transfer_states.agent_transfer_state(transfer.agent) ==
                               AgentTransferState::Aborting) {
                        aborted.push_back(transfer);
                    } else if (transfer.legacy_protocol && !transfer.legacy_handoff_sent &&
                               state.transfer_states.agent_transfer_state(transfer.agent) ==
                                   AgentTransferState::Cancelling) {
                        state.transfer_states.update_in_transit(transfer.agent, AgentTransferState::CleaningUp);
                        cancelled.push_back(transfer);
                    } else {
                        state.transfer_states.update_in_transit(transfer.agent, AgentTransferState::CleaningUp);
                        expired.push_back(transfer);
                        expired.back().failure_reason =
                            "Problems connecting to destination " + transfer.destination.name.value_or("") +
                            ", reason: Connection between viewer and destination region could not be established.";
                        if (transfer.legacy_protocol && transfer.legacy_handoff_sent)
                            expired.back().failure_reason = "Destination region did not signal teleport completion.";
                    }
                    return true;
                }
                if (state.transfer_states.agent_transfer_state(transfer.agent) == AgentTransferState::Aborting &&
                    (!transfer.legacy_protocol || !legacy_success)) {
                    aborted.push_back(transfer);
                    return true;
                }
                if ((transfer.legacy_protocol && legacy_success) ||
                    (!transfer.legacy_protocol &&
                     (transfer.confirmed ||
                      (!transfer.requires_callback && state.policies.teleport_arrived &&
                       state.policies.teleport_arrived(transfer.session, transfer.destination.id))))) {
                    if (!transfer.legacy_protocol)
                        state.transfer_states.set_agent_arrived_at_destination(transfer.agent);
                    state.transfer_states.update_in_transit(transfer.agent, AgentTransferState::CleaningUp);
                    arrived.push_back(transfer);
                    return true;
                }
                if (!transfer.legacy_protocol && transfer.expires > now)
                    return false;
                state.transfer_states.update_in_transit(transfer.agent, AgentTransferState::CleaningUp);
                expired.push_back(transfer);
                if (transfer.legacy_protocol)
                    expired.back().failure_reason =
                        legacy_error ? "Internal error" : "Destination region did not signal teleport completion.";
                return true;
            });
        }
        for (const auto &identity : superseded)
            state.release_transfer(identity);
        for (const auto &transfer : aborted)
            state.release_transfer({transfer.agent, transfer.session, transfer.generation, {}});
        for (auto &transfer : cancelled) {
            State::TransferRelease release{
                state, State::TransferIdentity{transfer.agent, transfer.session, transfer.generation, {}}};
            if (state.policies.cancel_teleport_destination)
                state.policies.cancel_teleport_destination(transfer.destination, transfer.agent, transfer.session);
            state.finish_failed_estate_ejection(transfer);
        }
        for (const auto &transfer : arrived) {
            State::TransferRelease release{
                state, State::TransferIdentity{transfer.agent, transfer.session, transfer.generation, {}}};
            const auto current = state.viewers->agent(transfer.agent);
            // A return arrival may replace the circuit before the previous
            // departure worker is observed. Retire that departure's state,
            // without demoting or closing the newer presence.
            if (transfer.source_circuit && (!current || current->circuit != transfer.source_circuit))
                continue;
            if (transfer.token.is_zero()) {
                state.retain_crossing_child(transfer);
                continue;
            }
            const auto viewer = state.viewers->agent(transfer.agent);
            if (viewer && viewer->circuit->session_id == transfer.session) {
                if (transfer.legacy_protocol) {
                    if (state.capability_runtime) {
                        auto seeds = state.capability_runtime->capabilities().copy_children_seeds(transfer.agent);
                        state.schedule_child_cleanup(std::move(seeds), transfer.agent, transfer.session,
                                                     transfer.destination, !transfer.requires_callback);
                    }
                    if (transfer.requires_callback) {
                        state.sessions.logout(transfer.session);
                        if (state.policies.departed_to_another_grid)
                            state.policies.departed_to_another_grid(*viewer);
                    }
                    const float distance =
                        std::clamp(viewer->draw_distance + 64.f, state.policies.min_region_view_distance,
                                   state.policies.max_region_view_distance);
                    const bool close =
                        transfer.requires_callback || transfer.destination.y == 0 ||
                        transfer_outside_view(distance, static_cast<std::uint32_t>(state.descriptor.x) >> 8,
                                              static_cast<std::uint32_t>(transfer.destination.x) >> 8,
                                              static_cast<std::uint32_t>(state.descriptor.y) >> 8,
                                              static_cast<std::uint32_t>(transfer.destination.y) >> 8,
                                              state.descriptor.size_x, state.descriptor.size_y,
                                              transfer.destination.size_x, transfer.destination.size_y);
                    if (state.retain_crossing_child(transfer) && close &&
                        state.begin_actor_close(transfer.agent, transfer.session, true)) {
                        const auto due = state.transfer_cleanup_now() + std::chrono::milliseconds(2000);
                        std::lock_guard lock(state.teleport_mutex);
                        state.legacy_departures.push_back({transfer, due});
                        release.enabled = false;
                    }
                    continue;
                }
                if (transfer.update_wait.valid()) {
                    const float distance =
                        std::clamp(viewer->draw_distance + 64.f, state.policies.min_region_view_distance,
                                   state.policies.max_region_view_distance);
                    const bool close =
                        transfer.requires_callback || transfer.destination.y == 0 ||
                        transfer_outside_view(distance, static_cast<std::uint32_t>(state.descriptor.x) >> 8,
                                              static_cast<std::uint32_t>(transfer.destination.x) >> 8,
                                              static_cast<std::uint32_t>(state.descriptor.y) >> 8,
                                              static_cast<std::uint32_t>(transfer.destination.y) >> 8,
                                              state.descriptor.size_x, state.descriptor.size_y,
                                              transfer.destination.size_x, transfer.destination.size_y);
                    // V2 resets the state machine before HasMovedAway/MakeChildAgent.
                    // Keep its close wait independent of the released transfer reservation.
                    if (close) {
                        std::lock_guard lock(state.teleport_mutex);
                        auto closing = transfer;
                        const auto identity = state.transfer_identities.find(transfer.agent);
                        if (identity != state.transfer_identities.end() &&
                            identity->second.generation == transfer.generation)
                            closing.confirmed = closing.confirmed || identity->second.arrival_confirmed;
                        state.v2_departures.push_back(
                            {std::move(closing), state.transfer_cleanup_now() + std::chrono::milliseconds(250), 60});
                    }
                    state.release_transfer(*release.identity);
                    release.enabled = false;
                    if (transfer.requires_callback) {
                        state.sessions.logout(transfer.session);
                        if (state.policies.departed_to_another_grid)
                            state.policies.departed_to_another_grid(*viewer);
                    }
                    state.retain_crossing_child(transfer);
                    if (state.capability_runtime) {
                        auto seeds = state.capability_runtime->capabilities().copy_children_seeds(transfer.agent);
                        state.schedule_child_cleanup(std::move(seeds), transfer.agent, transfer.session,
                                                     transfer.destination, !transfer.requires_callback);
                    }
                    continue;
                }
                {
                    std::lock_guard lock(state.teleport_mutex);
                    if (transfer.requires_callback)
                        state.departing_foreign_sessions.insert(transfer.session);
                    else
                        state.departing_local_sessions.insert(transfer.session);
                }
                if (state.capability_runtime) {
                    auto seeds = state.capability_runtime->capabilities().copy_children_seeds(transfer.agent);
                    state.schedule_child_cleanup(std::move(seeds), transfer.agent, transfer.session,
                                                 transfer.destination, !transfer.requires_callback);
                }
                state.viewers->transport().remove_client_if_session(transfer.agent, transfer.session);
            }
        }
        for (auto &transfer : expired) {
            State::TransferRelease release{
                state, State::TransferIdentity{transfer.agent, transfer.session, transfer.generation, {}}};
            const auto current = state.viewers->agent(transfer.agent);
            if (transfer.source_circuit && (!current || current->circuit != transfer.source_circuit))
                continue;
            if (transfer.update_wait.valid()) {
                if (!state.viewers->set_transfer_child(transfer.agent, transfer.session, false,
                                                       transfer.source_circuit))
                    continue;
                std::lock_guard actors_lock(state.actors_mutex);
                const auto actor = state.actors.find(transfer.agent);
                if (actor != state.actors.end() && actor->second->session == transfer.session)
                    actor->second->root = true;
            }
            if (state.policies.cancel_teleport_destination)
                state.policies.cancel_teleport_destination(transfer.destination, transfer.agent, transfer.session);
            auto failure = lludp::make_packet("TeleportFailed");
            auto &info = failure.block("Info");
            info["AgentID"] = transfer.agent;
            const auto reason = transfer.failure_reason.empty() ? "Destination did not confirm teleport arrival"
                                                                : transfer.failure_reason;
            std::vector<std::uint8_t> reason_bytes(reason.begin(), reason.end());
            reason_bytes.push_back(0);
            info["Reason"] = std::move(reason_bytes);
            state.viewers->transport().enqueue_if_session(transfer.agent, transfer.session, std::move(failure),
                                                          ThrottleOutPacketType::Unknown);
            state.finish_failed_estate_ejection(transfer);
        }
    }
    {
        std::vector<State::PendingTeleport> due;
        {
            std::lock_guard lock(state.teleport_mutex);
            const auto now = state.transfer_cleanup_now();
            std::erase_if(state.legacy_departures, [&](const auto &entry) {
                if (entry.due > now)
                    return false;
                due.push_back(entry.transfer);
                return true;
            });
        }
        for (const auto &transfer : due) {
            State::TransferIdentity identity{transfer.agent, transfer.session, transfer.generation, {}};
            State::TransferRelease release{state, identity};
            bool current;
            {
                std::lock_guard lock(state.teleport_mutex);
                current = state.owns_transfer_locked(identity);
            }
            if (current && state.begin_actor_close(transfer.agent, transfer.session, false))
                state.viewers->transport().remove_client_if_session(transfer.agent, transfer.session);
        }
    }
    {
        std::vector<State::PendingTeleport> closing;
        {
            std::lock_guard lock(state.teleport_mutex);
            const auto now = state.transfer_cleanup_now();
            std::erase_if(state.v2_departures, [&](auto &entry) {
                if (entry.next_poll > now)
                    return false;
                const auto viewer = state.viewers->agent(entry.transfer.agent);
                if (!viewer || viewer->circuit->session_id != entry.transfer.session)
                    return true;
                if (entry.close_attempted)
                    return entry.transfer.confirmed;
                if (entry.transfer.confirmed || --entry.polls_left == 0) {
                    closing.push_back(entry.transfer);
                    entry.close_attempted = true;
                    return entry.transfer.confirmed;
                }
                entry.next_poll = now + std::chrono::milliseconds(250);
                return false;
            });
        }
        for (const auto &transfer : closing)
            if (state.begin_actor_close(transfer.agent, transfer.session, false) &&
                state.viewers->transport().remove_client_if_session(transfer.agent, transfer.session)) {
                std::lock_guard lock(state.teleport_mutex);
                std::erase_if(state.v2_departures, [&](const auto &entry) {
                    return entry.transfer.agent == transfer.agent && entry.transfer.session == transfer.session &&
                           entry.transfer.generation == transfer.generation;
                });
            }
    }
    const bool simulate_physics = (state.region_flags() & 0x4000u) == 0;
    if (!simulate_physics) {
        state.physics_activation_attempted = false;
    } else if (!state.physics_activation_attempted && !state.viewer_physics.load()) {
        try {
            state.activate_physics();
        } catch (const std::exception &failure) {
            state.error(std::string("Region physics activation failed: ") + failure.what());
        }
    }
    state.poll_keyframed_motions();
    const bool update_object_groups = state.object_updates_due(std::chrono::steady_clock::now());
    ViewerPhysics::PollResult physics_sample;
    if (const auto physics = state.viewer_physics.load()) {
        physics_sample = physics->poll(simulate_physics, update_object_groups);
        const auto &sample = physics_sample;
        state.stats_physics_steps += sample.steps;
        state.stats_physical_parts = sample.physical_parts;
        state.stats_physics_ms += sample.solver_ms;
        state.stats_agent_ns.fetch_add(static_cast<std::int64_t>(sample.agent_ms * 1000000.),
                                       std::memory_order_relaxed);
    }
    state.remove_estate_disabled_scripts();
    state.run_inventory();
    state.finish_avatar_crossings(false);
    state.finish_object_crossings(false);
    state.run_script_updates();
    state.run_inventory_scripts();
    state.deliver_script_http_events();
    const auto reparented = state.viewers->refresh_seated_positions();
    state.update_wind();
    if (state.scripts_enabled()) {
        state.poll_script_targets();
        state.poll_script_sensors();
    }
    state.run_scripts();
    state.publish_impact_sounds(physics_sample.prim_collision_reports);
    state.publish_prim_collisions(physics_sample.prim_collision_reports);
    state.publish_attachment_collisions(physics_sample.prim_collision_reports);
    state.heal_avatars();
    state.apply_avatar_collision_damage(physics_sample.prim_collision_reports);
    state.run_land_stats_requests();
    const auto scene_updates_start = std::chrono::steady_clock::now();
    state.world.expire_temporary_objects(scene_updates_start);
    state.world.expire_particle_systems(scene_updates_start);
    state.run_parcel_return_requests();
    state.return_expired_parcel_objects(scene_updates_start);
    state.refresh_avatar_parcel_views();
    state.close_kicked_viewers();
    state.expire_parcel_freezes();
    state.run_task_inventory();
    state.send_due_appearances();
    state.send_coarse_locations();
    state.save_due_appearances();
    state.send_due_wearables();
    state.flush_objects(update_object_groups);
    if (update_object_groups) {
        state.check_neighbour_views();
        state.send_child_positions();
    }
    state.backup_legacy_materials(false);
    for (const auto &moved : reparented) {
        const auto current = state.viewers->agent(moved.circuit->agent_id);
        if (!current || !current->seat || current->seat->order != moved.seat->order ||
            current->circuit->session_id != moved.circuit->session_id)
            continue;
        for (const auto &recipient : state.viewers->agents())
            if (recipient.root)
                state.send_avatar(*current, recipient);
    }
    state.viewers->broadcast_terrain_changes();
    state.stats_other_ms +=
        std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - scene_updates_start).count();
    state.viewers->poll();
    state.finish_pending_terrain_seeds();
    state.send_textures();
}

void RegionRuntime::prepare_stop() {
    auto s = state_;
    s->quiesce_updates();
    std::lock_guard lock(s->new_mutex);
    s->running = false;
}

void RegionRuntime::stop(const std::function<void()> &save_scene) {
    auto s = state_;
    prepare_stop();
    std::exception_ptr first;
    auto attempt = [&](auto &&cleanup) {
        try {
            cleanup();
        } catch (...) {
            if (!first)
                first = std::current_exception();
        }
    };
    attempt([&] {
        std::vector<std::shared_future<bool>> waiting;
        {
            std::lock_guard lock(s->teleport_mutex);
            waiting.swap(s->transfer_workers);
        }
        for (const auto &work : waiting)
            work.wait();
    });
    attempt([&] { s->finish_avatar_crossings(true); });
    attempt([&] {
        if (s->policies.script_remote_data_channels)
            s->policies.script_remote_data_channels->cancel_region(s->descriptor.id);
    });
    attempt([&] {
        if (s->policies.script_outbound_http)
            s->policies.script_outbound_http->stop_all();
    });
    attempt([&] {
        if (s->socket)
            s->socket->stop();
    });
    attempt([&] {
        if (s->map_worker.joinable()) {
            s->map_worker.request_stop();
            s->map_worker.join();
        }
    });
    attempt([&] {
        for (auto &worker : s->remote_map_workers)
            worker.request_stop();
        for (auto &worker : s->remote_map_workers)
            if (worker.joinable())
                worker.join();
    });
    // Delayed appearance writes still need their live presence and session.
    // Flush after inbound work stops and before closing the viewer presences.
    attempt([&] { s->save_due_appearances(true); });
    attempt([&] {
        if (s->viewers)
            s->viewers->close();
    });
    attempt([&] { s->flush_attachment_logout_states(); });
    attempt([&] { s->finish_attachment_detaches(true); });
    s->viewer_physics.store(nullptr);
    attempt([&] {
        if (s->basic_profiles)
            s->basic_profiles->stop();
    });
    s->basic_profiles.reset();
    attempt([&] {
        if (s->capability_runtime)
            s->capability_runtime->shutdown();
    });
    s->capability_runtime.reset();
    for (const auto &[agent, circuit] : s->circuits.get_agent_circuits()) {
        attempt([&] { s->circuits.remove_circuit(circuit); });
        const bool incoming = std::any_of(s->incoming_teleports.begin(), s->incoming_teleports.end(),
                                          [&](const auto &transfer) { return transfer.first == circuit; });
        if (incoming)
            continue;
        attempt([&] { s->sessions.logout(circuit->session_id); });
        if (s->policies.logged_out) {
            attempt([&] {
                ViewerAgent pending;
                pending.circuit = circuit;
                pending.position = circuit->start_position;
                s->policies.logged_out(pending);
            });
        }
    }
    {
        std::lock_guard lock(s->new_mutex);
        s->incoming_teleports.clear();
        s->incoming_attachments.clear();
        s->incoming_object_attachments.clear();
        s->arrival_callbacks.clear();
    }
    {
        std::lock_guard lock(s->teleport_mutex);
        s->pending_teleports.clear();
        s->legacy_departures.clear();
        s->v2_departures.clear();
        for (const auto &[agent, identity] : s->transfer_identities)
            s->transfer_states.reset_from_transit(agent);
        s->transfer_identities.clear();
        s->departing_foreign_sessions.clear();
        s->departing_local_sessions.clear();
    }
    attempt([&] { s->finish_object_crossings(true); });
    attempt([&] { s->backup_legacy_materials(true); });
    if (save_scene)
        attempt(save_scene);
    attempt([&] { s->sessions.logout_region(s->descriptor.id); });
    {
        std::lock_guard lock(s->script_http_mutex);
        for (const auto &[id, url] : s->script_urls)
            s->script_url_listener(url.secure)->routes.remove_poll(s->script_url_prefix(url.secure) + id.str());
        s->script_urls.clear();
        s->script_http_requests.clear();
        s->script_http_events.clear();
    }
    s->scripts.clear();
    s->script_listeners.clear();
    s->script_targets.clear();
    s->script_sensors.clear();
    s->next_sensor_sweep = 0.;
    s->incoming_script_checkpoints.clear();
    s->incoming_managed_script_states.clear();
    s->incoming_controls.clear();
    s->captured_controls.clear();
    s->viewer_script_controls.clear();
    s->dataserver_requests.clear();
    s->dataserver_lookup.reset();
    s->active_scripts.store(0, std::memory_order_relaxed);
    {
        std::lock_guard lock(s->task_data_mutex);
        s->task_parts.clear();
    }
    s->task_recipient.reset();
    {
        std::lock_guard lock(s->inventory_mutex);
        s->inventory_items.clear();
        s->inventory_folders.clear();
        s->inventory_items_running = s->inventory_folders_running = false;
    }
    {
        std::lock_guard lock(s->commands_mutex);
        s->script_commands.clear();
        s->viewer_script_chat.clear();
        s->attachment_detach_requests.clear();
        s->login_attachment_restores.clear();
        s->task_commands.clear();
        s->inventory_script_commands.clear();
        s->parcel_return_requests.clear();
        s->edge_return_requests.clear();
        s->pending_derez_returns.clear();
    }
    if (first)
        std::rethrow_exception(first);
}

std::shared_ptr<const framework::AgentCircuitData::ServiceUrls> RegionRuntime::profile_service_urls(Uuid id) const {
    const auto &state = state_;
    if (!state->running || !state->viewers)
        return {};
    auto circuit = state->circuits.get_agent_circuit_data(id);
    if (!circuit || !circuit->service_urls)
        return {};
    return std::make_shared<const framework::AgentCircuitData::ServiceUrls>(*circuit->service_urls);
}

std::shared_ptr<ProfileRequestPresence> RegionRuntime::profile_presence(Uuid id) const {
    return state_->profile_presence(id);
}

bool RegionRuntime::kick_viewer(Uuid id, std::u16string_view reason) {
    auto state = state_;
    if (!state->running || !state->viewers)
        return false;
    const auto viewer = state->viewers->agent(id);
    if (!viewer)
        return false;
    if (viewer->root) {
        state->send_kick(*viewer, reason);
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
    }
    return state->viewers->transport().remove_client_if_session(id, viewer->circuit->session_id);
}

bool RegionRuntime::deliver_instant_message(const RegionInstantMessage &message) {
    return state_->deliver_instant_message(message);
}

bool RegionRuntime::deliver_instant_message_to_child(const RegionInstantMessage &message) {
    return state_->deliver_instant_message(message, {}, false, {}, true);
}

bool RegionRuntime::receive_grid_instant_message(const RegionInstantMessage &message) {
    if (state_->policies.viewer_instant_messages_enabled ||
        (message.dialog != 0 && message.dialog != 19 && message.dialog != 20 && message.dialog != 41 &&
         message.dialog != 42))
        return deliver_instant_message(message);

    // The grid acknowledges the root presence even when its text handler is disabled.
    if (!state_->running || !state_->viewers)
        return false;
    const auto viewer = state_->viewers->agent(message.recipient);
    return viewer && viewer->root && !viewer->logout_requested;
}

bool RegionRuntime::deliver_instant_message_failure(const RegionInstantMessage &message) {
    if (!message.sender_viewer_session || message.recipient.is_zero() || (message.dialog != 0 && message.dialog != 20))
        return false;

    RegionInstantMessage reply;
    reply.sender = message.sender;
    reply.recipient = message.recipient;
    reply.dialog = 20;
    reply.sender_name = u"System";
    reply.message = u"Unable to send instant message. User is not logged in.";
    reply.timestamp = static_cast<std::uint32_t>(user_inventory_unix_time());
    return state_->deliver_instant_message(reply, message.sender_viewer_session, false, message.sender);
}

bool RegionRuntime::receive_grid_moderation(const RegionInstantMessage &message) {
    if (!state_->running || !state_->viewers || message.bucket.empty())
        return false;
    static const Uuid service_god("6571e388-6218-4574-87db-f9379718315e");
    if (message.sender != service_god) {
        const auto sender = state_->viewers->agent(message.sender);
        const auto *viewer = sender ? &*sender : nullptr;
        const auto level = state_->moderation_level(message.sender, viewer);
        return state_->moderate_user(message.sender, viewer, level, message.recipient, message.bucket.front(),
                                     message.message, false);
    }
    const auto target = state_->viewers->agent(message.recipient);
    if (!target || !target->root)
        return false;
    if (state_->agent_god_level(message.recipient, target->circuit->session_id) >= 240) {
        alert_viewer(message.recipient,
                     "GRID kick detected and ignored, kick reason: " + framework::utf8(message.message));
        return true;
    }
    state_->send_kick(*target, message.message);
    std::this_thread::sleep_for(std::chrono::milliseconds(500));
    return state_->viewers->transport().remove_client_if_session(message.recipient, target->circuit->session_id);
}

bool RegionRuntime::notify_friend_rights(Uuid recipient, Uuid principal, std::int32_t previous, std::int32_t granted) {
    return state_->notify_friend_rights(recipient, principal, previous, granted);
}

bool RegionRuntime::notify_friend_termination(Uuid recipient, Uuid former_friend) {
    return state_->notify_friend_termination(recipient, former_friend);
}

bool RegionRuntime::notify_inventory_item(const services::InventoryItem &item) {
    const auto state = state_;
    if (!state->running || !state->viewers || !state->capability_runtime)
        return false;
    const auto viewer = state->viewers->agent(item.owner);
    if (!viewer || !viewer->root || viewer->logout_requested)
        return false;
    const auto queue = state->capability_runtime->event_queue();
    if (!queue)
        return false;
    queue->bulk_inventory(&item, item.owner);
    return true;
}

bool RegionRuntime::alert_viewer(Uuid recipient, const std::string &message) {
    auto state = state_;
    if (!state->running || !state->viewers)
        return false;
    const auto viewer = state->viewers->agent(recipient);
    if (!viewer || !viewer->root || viewer->logout_requested)
        return false;
    return state->viewers->transport().enqueue_if_session(
        recipient, viewer->circuit->session_id, agent_alert(recipient, message, false), ThrottleOutPacketType::Task);
}

bool RegionRuntime::notify_friend_status(Uuid recipient, Uuid friend_id, bool online,
                                         std::optional<Uuid> expected_session) {
    auto state = state_;
    if (!state->running || !state->viewers)
        return false;
    const auto viewer = state->viewers->agent(recipient);
    if (!viewer || !viewer->root || viewer->logout_requested ||
        (expected_session && viewer->circuit->session_id != *expected_session))
        return false;
    if (state->policies.friends_online_cache)
        state->policies.friends_online_cache->update(recipient, std::span<const Uuid>(&friend_id, 1), online);
    auto packet = lludp::make_packet(online ? "OnlineNotification" : "OfflineNotification");
    auto agent = lludp::make_block(packet.spec->blocks[0]);
    agent["AgentID"] = friend_id;
    packet.blocks["AgentBlock"].push_back(std::move(agent));
    return state->viewers->transport().enqueue_if_session(recipient, viewer->circuit->session_id, std::move(packet),
                                                          ThrottleOutPacketType::Task);
}

std::optional<HttpResponse> RegionRuntime::region_map_image(const HttpRequest &request) const {
    auto &state = *state_;
    if (!state.policies.map_layer_enabled || !state.running || request.path != "/index.php")
        return {};
    const auto query = request.raw_target.find('?');
    if (query == std::string::npos)
        return {};
    const auto form = parse_service_form(std::string_view(request.raw_target).substr(query + 1));
    const auto found = form.find("method");
    const auto method = found == form.end() ? nullptr : std::get_if<std::string>(&found->second);
    auto expected = "regionImage" + state.descriptor.id.str();
    std::erase(expected, '-');
    if (!method || *method != expected)
        return {};
    HttpResponse response;
    response.keep_alive = false;
    response.status = 404;
    if (request.method != "GET" || !state.policies.load_asset || !state.policies.encode_map_jpeg)
        return response;
    try {
        std::lock_guard lock(state.region_map_image_mutex);
        const auto image = state.generated_terrain_map.value_or(state.descriptor.terrain_image);
        if (image.is_zero())
            return response;
        if (state.region_map_jpeg.empty()) {
            const auto asset = state.policies.load_asset(image);
            if (asset && asset->data && !asset->data->empty())
                state.region_map_jpeg = state.policies.encode_map_jpeg(*asset->data);
        }
        if (!state.region_map_jpeg.empty()) {
            response.status = 200;
            response.content_type = "image/jpeg";
            response.body = state.region_map_jpeg;
        }
    } catch (const std::exception &error) {
        state.error(std::string("Unable to generate map image: ") + error.what());
    }
    return response;
}

std::optional<HttpResponse> RegionRuntime::remote_map_items(const HttpRequest &request) const {
    auto &state = *state_;
    if (!state.policies.map_layer_enabled || !state.running ||
        request.path != "/MAP/MapItems/" + std::to_string(state.descriptor.handle()))
        return {};
    HttpResponse response;
    response.content_type = "application/xml+llsd";
    auto result = Value::object({});
    for (const auto type : {State::map_agents, state.map_sale_type(), State::map_telehub}) {
        const auto items = state.collect_map_items(type, std::nullopt);
        if (items.empty() && type != State::map_agents)
            continue;
        Value array;
        array.kind = Value::Kind::Array;
        for (const auto &item : items) {
            Value id(item.id.str());
            id.kind = Value::Kind::Uuid;
            array.array.push_back(Value::object({{"X", Value(std::bit_cast<std::int32_t>(item.x))},
                                                 {"Y", Value(std::bit_cast<std::int32_t>(item.y))},
                                                 {"ID", std::move(id)},
                                                 {"Name", Value(item.name)},
                                                 {"Extra", Value(item.extra)},
                                                 {"Extra2", Value(item.extra2)}}));
        }
        result.set(std::to_string(type), std::move(array));
    }
    response.body = llsd_xml(result);
    return response;
}

void RegionRuntime::clear_remote_map_failure(std::uint64_t handle) {
    std::lock_guard lock(state_->remote_map_mutex);
    const auto entry = state_->remote_map_cache.find(handle);
    if (entry != state_->remote_map_cache.end() && !entry->second.response)
        state_->remote_map_cache.erase(entry);
}

GridRegion RegionRuntime::descriptor() const {
    auto region = state_->descriptor;
    {
        std::lock_guard lock(state_->region_map_image_mutex);
        region.terrain_image = state_->generated_terrain_map.value_or(region.terrain_image);
        region.parcel_image = state_->generated_parcel_map.value_or(region.parcel_image);
    }
    region.estate_owner = state_->estate_settings.load()->owner;
    region.maturity = state_->region_maturity;
    region.access = state_->region_access;
    return region;
}

std::string RegionRuntime::estate_name() const {
    return state_->estate_settings.load()->estate_name;
}

bool RegionRuntime::ready() const {
    return state_->running.load();
}

static Uuid snapshot_object_image(const SceneObject &object) {
    constexpr std::uint8_t square_profile = 1;
    if ((object.shape.profile_curve & 0x0fu) != square_profile)
        return {};
    static const Uuid default_image("89556747-24cb-43ed-920b-47caed15465f");
    try {
        const TextureEntry textures(object.texture_entry);
        if (!textures.default_texture)
            return {};
        const auto eligible = [&](const framework::TextureFace &face) {
            const auto id = face.texture_id();
            return !id.is_zero() && id != default_image && id != TextureEntry::white_texture && face.color()[3] < 50.f;
        };
        framework::OrderedDictionary<Uuid, int, framework::UuidHash> counts;
        const auto default_id = textures.default_texture->texture_id();
        if (eligible(*textures.default_texture))
            counts[default_id] = 8;
        for (const auto &face : textures.faces) {
            if (!face || !eligible(*face))
                continue;
            ++counts[face->texture_id()];
            if (counts.contains(default_id))
                --counts[default_id];
        }
        Uuid image;
        auto fewest = std::numeric_limits<int>::max();
        for (const auto &[id, count] : counts)
            if (count > 0 && count < fewest) {
                image = id;
                fewest = count;
            }
        return image;
    } catch (const std::out_of_range &) {
        return {};
    }
}

std::uint64_t RegionRuntime::data_snapshot_revision() const {
    return state_->data_snapshot_changes.load(std::memory_order_relaxed);
}

static std::filesystem::path snapshot_filename(const std::filesystem::path &directory, std::string name) {
    constexpr std::string_view invalid = "<>:\"/\\|?*.";
    for (char &character : name)
        if (static_cast<unsigned char>(character) < 32 || invalid.find(character) != std::string_view::npos)
            character = '_';
    return directory / framework::utf8_path(name + ".xml");
}

static void write_snapshot_file(const std::filesystem::path &path, pugi::xml_node node) {
    auto temporary = path;
    temporary += "." + Uuid::random().str() + ".tmp";
    try {
        pugi::xml_document document;
        document.append_copy(node);
        std::ofstream stream(temporary, std::ios::binary | std::ios::trunc);
        stream.exceptions(std::ios::badbit | std::ios::failbit);
        document.save(stream, "  ");
        stream.close();
        std::filesystem::rename(temporary, path);
    } catch (...) {
        std::error_code ignored;
        std::filesystem::remove(temporary, ignored);
        throw;
    }
}

std::string RegionRuntime::read_data_snapshot_cache(const std::filesystem::path &directory) const {
    if (directory.empty())
        return {};
    const auto region = descriptor();
    try {
        std::ifstream stream(snapshot_filename(directory, region.name.value_or("")), std::ios::binary);
        pugi::xml_document cached;
        if (!stream || !cached.load(stream))
            return {};
        const auto node = cached.child("region");
        if (std::string_view(node.child("info").child_value("uuid")) != region.id.str())
            return {};
        pugi::xml_document response;
        response.append_child("regiondata").append_copy(node);
        std::ostringstream xml;
        response.save(xml, "", pugi::format_raw);
        return xml.str();
    } catch (const std::exception &) {
        return {};
    }
}

std::string RegionRuntime::data_snapshot(std::string_view requested_region, int period, std::string_view grid_name,
                                         std::string_view gatekeeper, bool expose_all_parcels,
                                         const std::filesystem::path &cache_directory) const {
    const auto region = descriptor();
    const auto name = region.name.value_or("");
    pugi::xml_document document;
    if (!requested_region.empty() && requested_region != name) {
        auto error = document.append_child("error");
        error.append_child("region").text().set(std::string(requested_region).c_str());
        error.append_child("exception").text().set("Unknown region");
    } else {
        auto data = document.append_child("regiondata");
        if (requested_region.empty())
            data.append_child("expire").text().set(period);
        auto node = data.append_child("region");
        const auto category = region.maturity == 0   ? "PG"
                              : region.maturity == 1 ? "Mature"
                              : region.maturity == 2 ? "Adult"
                                                     : "Unknown";
        node.append_attribute("category").set_value(category);
        const auto object_revision = state_->snapshot_object_changes.load(std::memory_order_acquire);
        const auto objects = state_->world.objects();
        const auto roots = std::ranges::count_if(objects, [](const auto &object) { return !object.parent_id; });
        const auto avatars = state_->viewers ? state_->viewers->agents().size() : 0;
        node.append_attribute("entities").set_value(static_cast<unsigned long long>(roots + avatars));
        auto info = node.append_child("info");
        info.append_child("uuid").text().set(region.id.str().c_str());
        info.append_child("url").text().set(region.server_uri().c_str());
        info.append_child("name").text().set(name.c_str());
        info.append_child("handle").text().set(static_cast<unsigned long long>(region.handle()));
        auto grid = node.append_child("grid");
        if (!gatekeeper.empty())
            grid.append_child("gatekeeperURL").text().set(std::string(gatekeeper).c_str());
        grid.append_child("name").text().set(std::string(grid_name).c_str());
        auto region_data = node.append_child("data");
        std::unique_lock fragment_lock(state_->snapshot_fragments_mutex, std::defer_lock);
        if (!cache_directory.empty())
            fragment_lock.lock();
        const bool reuse_fragments =
            fragment_lock.owns_lock() && state_->snapshot_fragments_directory == cache_directory;
        const auto read_fragment = [&](const char *suffix, const char *tag) -> pugi::xml_node {
            try {
                std::ifstream stream(snapshot_filename(cache_directory, name + suffix), std::ios::binary);
                pugi::xml_document fragment;
                if (stream && fragment.load(stream)) {
                    if (const auto root = fragment.child(tag))
                        return region_data.append_copy(root);
                }
            } catch (const std::exception &) {
                // A missing or unreadable fragment is rebuilt from the region.
            }
            return {};
        };
        auto estate = reuse_fragments ? read_fragment("_EstateSnapshot", "estate") : pugi::xml_node{};
        const bool estate_rebuilt = !estate;
        if (estate_rebuilt) {
            estate = region_data.append_child("estate");
            if (state_->policies.script_account) {
                if (const auto account = state_->policies.script_account(region.estate_owner)) {
                    auto user = estate.append_child("user");
                    user.append_child("name").text().set(account->name().c_str());
                    user.append_child("uuid").text().set(region.estate_owner.str().c_str());
                }
            }
            estate.append_child("name").text().set(state_->estate_settings.load()->estate_name.c_str());
            estate.append_child("id").text().set(state_->estate_settings.load()->estate_id);
            estate.append_child("parentid").text().set(state_->estate_settings.load()->parent_estate_id);
            auto estate_flags = estate.append_child("flags");
            estate_flags.append_attribute("teleport").set_value(state_->allows_direct_teleport() ? "True" : "False");
            constexpr std::uint32_t public_access = 0x8000u;
            const bool public_estate =
                (state_->estate_settings.load()->estate_handshake_only_flags & public_access) != 0;
            estate_flags.append_attribute("public").set_value(public_estate ? "True" : "False");
        }
        pugi::xml_node object_data;
        if (reuse_fragments && object_revision == state_->cached_snapshot_object_revision)
            object_data = read_fragment("_ObjectSnapshot", "objectdata");
        const bool objects_rebuilt = !object_data;
        if (objects_rebuilt) {
            object_data = region_data.append_child("objectdata");
            constexpr std::uint32_t include_in_search = 0x8000u;
            for (const auto &object : objects) {
                if (object.parent_id || object.is_attachment || !(object.flags & include_in_search))
                    continue;
                const auto parcel = state_->parcel_at_truncated_position(object.position);
                if (!parcel)
                    continue;
                auto entry = object_data.append_child("object");
                entry.append_child("uuid").text().set(object.id.str().c_str());
                entry.append_child("title").text().set(object.name.c_str());
                entry.append_child("description").text().set(object.description.c_str());
                std::ostringstream flags;
                flags << std::hex << object.flags;
                entry.append_child("flags").text().set(flags.str().c_str());
                entry.append_child("regionuuid").text().set(region.id.str().c_str());
                entry.append_child("parceluuid").text().set(parcel->id.str().c_str());
                std::ostringstream position;
                position << object.position.x << '/' << object.position.y << '/' << object.position.z;
                entry.append_child("location").text().set(position.str().c_str());
                if (const auto image = snapshot_object_image(object); !image.is_zero())
                    entry.append_child("image").text().set(image.str().c_str());
            }
        }
        auto parcel_data = region_data.append_child("parceldata");
        std::map<Uuid, std::string> group_names;
        if (state_->policies.list_parcels) {
            for (const auto &parcel : state_->policies.list_parcels()) {
                constexpr std::uint32_t show_directory = 1u << 12;
                if (!parcel || (!expose_all_parcels && !(parcel->flags & show_directory)))
                    continue;

                auto entry = parcel_data.append_child("parcel");
                const auto flag = [&](const char *attribute, std::uint32_t mask, bool invert = false) {
                    const bool enabled = (parcel->flags & mask) != 0;
                    entry.append_attribute(attribute).set_value(enabled != invert ? "true" : "false");
                };
                flag("showinsearch", show_directory);
                flag("scripts", 1u << 1);
                flag("build", 1u << 6);
                flag("public", 1u << 9, true);
                entry.append_attribute("category").set_value(parcel->category);
                flag("forsale", 1u << 2);
                entry.append_attribute("salesprice").set_value(parcel->sale_price);
                entry.append_child("name").text().set(parcel->name.c_str());
                entry.append_child("description").text().set(parcel->description.c_str());
                entry.append_child("uuid").text().set(parcel->id.str().c_str());
                entry.append_child("area").text().set(parcel->area);

                const auto [minimum, maximum] = state_->parcel_geometry(*parcel);
                const Vector3d center{(minimum.x + maximum.x) * .5, (minimum.y + maximum.y) * .5,
                                      (minimum.z + maximum.z) * .5};
                const auto location = parcel->landing_point == Vector3d{} ? center : parcel->landing_point;
                std::ostringstream position;
                position << location.x << '/' << location.y << '/' << location.z;
                entry.append_child("location").text().set(position.str().c_str());
                const auto contains = [&](double x, double y) {
                    if (!(x >= 0 && x < region.size_x && y >= 0 && y < region.size_y))
                        return false;
                    const auto match = state_->parcel_at_truncated_position({float(x), float(y), 0});
                    return match && match->id == parcel->id;
                };
                auto point = contains(location.x, location.y) ? location : center;
                if (!contains(point.x, point.y)) {
                    constexpr int land_unit = 4;
                    bool found = false;
                    for (int y = static_cast<int>(minimum.y); y <= maximum.y && !found; y += land_unit)
                        for (int x = static_cast<int>(minimum.x); x <= maximum.x; x += land_unit)
                            if (contains(x, y)) {
                                point.x = x;
                                point.y = y;
                                found = true;
                                break;
                            }
                }
                const auto info_id =
                    framework::build_fake_parcel_id(region.handle(), std::uint32_t(point.x), std::uint32_t(point.y));
                entry.append_child("infouuid").text().set(info_id.str().c_str());
                const auto dwell = state_->policies.parcel_dwell_enabled ? state_->current_parcel_dwell(*parcel) : 0.f;
                entry.append_child("dwell").text().set(dwell);
                if (!parcel->snapshot_id.is_zero())
                    entry.append_child("image").text().set(parcel->snapshot_id.str().c_str());
                std::string group_name;
                if (!parcel->group.is_zero()) {
                    auto [cached, inserted] = group_names.try_emplace(parcel->group);
                    if (inserted && state_->policies.group_record_name)
                        cached->second = state_->policies.group_record_name(parcel->group).value_or("");
                    group_name = cached->second;
                    auto group_entry = entry.append_child("group");
                    group_entry.append_child("groupuuid").text().set(parcel->group.str().c_str());
                    group_entry.append_child("groupname").text().set(group_name.c_str());
                }
                auto owner = entry.append_child("owner");
                owner.append_child("uuid").text().set(parcel->owner.str().c_str());
                if (parcel->group_owned) {
                    owner.append_child("name").text().set(group_name.c_str());
                } else {
                    try {
                        const auto account = state_->policies.script_account
                                                 ? state_->policies.script_account(parcel->owner)
                                                 : std::nullopt;
                        const auto owner_name = account ? account->name() : "UnKnown";
                        owner.append_child("name").text().set(owner_name.c_str());
                    } catch (const std::exception &) {
                        // The managed provider omits the owner name when the account lookup fails.
                    }
                }
            }
        }
        if (!cache_directory.empty()) {
            try {
                std::filesystem::create_directories(cache_directory);
                if (estate_rebuilt)
                    write_snapshot_file(snapshot_filename(cache_directory, name + "_EstateSnapshot"), estate);
                if (objects_rebuilt)
                    write_snapshot_file(snapshot_filename(cache_directory, name + "_ObjectSnapshot"), object_data);
                write_snapshot_file(snapshot_filename(cache_directory, name + "_LandSnapshot"), parcel_data);
                write_snapshot_file(snapshot_filename(cache_directory, name), node);
                state_->snapshot_fragments_directory = cache_directory;
                state_->cached_snapshot_object_revision = object_revision;
            } catch (const std::exception &) {
                state_->error("DataSnapshot could not write its disk cache");
            }
        }
    }
    std::ostringstream xml;
    document.save(xml, "", pugi::format_raw);
    return xml.str();
}

network::Value RegionRuntime::land_data(std::uint64_t handle, std::uint32_t x, std::uint32_t y,
                                        bool include_group_ownership) const {
    const auto &state = *state_;
    if (!state.running || !state.policies.script_parcel_at)
        return Value::object({});
    const auto origin_x = static_cast<std::uint32_t>(state.descriptor.x);
    const auto origin_y = static_cast<std::uint32_t>(state.descriptor.y);
    const auto world_x = static_cast<std::uint32_t>(handle >> 32) + x;
    const auto world_y = static_cast<std::uint32_t>(handle) + y;
    if (world_x < origin_x || world_y < origin_y ||
        world_x - origin_x >= static_cast<std::uint32_t>(state.descriptor.size_x) ||
        world_y - origin_y >= static_cast<std::uint32_t>(state.descriptor.size_y))
        return Value::object({});
    const auto parcel = state.policies.script_parcel_at(
        {static_cast<float>(world_x - origin_x), static_cast<float>(world_y - origin_y), 0});
    if (!parcel)
        return Value::object({});

    const auto [minimum, maximum] = state.parcel_geometry(*parcel);
    const auto vector_text = [](const Vector3d &value) {
        return framework::vector3_string(
            {static_cast<float>(value.x), static_cast<float>(value.y), static_cast<float>(value.z)});
    };
    const auto dwell = double(state.current_parcel_dwell(*parcel));
    auto result = Value::object({
        {"AABBMax", Value(vector_text(maximum))},
        {"AABBMin", Value(vector_text(minimum))},
        {"Area", Value(std::to_string(parcel->area))},
        {"AuctionID", Value(std::to_string(parcel->auction_id))},
        {"Description", Value(parcel->description)},
        {"Flags", Value(std::to_string(parcel->flags))},
        {"GlobalID", Value(parcel->id.str())},
        {"Name", Value(parcel->name)},
        {"OwnerID", Value(parcel->owner.str())},
        {"SalePrice", Value(std::to_string(parcel->sale_price))},
        {"SnapshotID", Value(parcel->snapshot_id.str())},
        {"UserLocation", Value(vector_text(parcel->landing_point))},
        {"RegionAccess", Value(std::to_string(state.region_access.load()))},
        {"Dwell", Value(osd_string(environment_real(state.policies.parcel_dwell_enabled ? std::trunc(dwell) : dwell)))},
    });
    if (include_group_ownership)
        result.set("IsGroupOwned", Value(parcel->group_owned));
    return result;
}

World &RegionRuntime::world() {
    return state_->world;
}

void RegionRuntime::gather_region_asset_references(UuidGatherer &gatherer) const {
    {
        std::lock_guard lock(state_->terrain_texture_mutex);
        for (const auto texture : state_->terrain_texture_assets)
            gatherer.add_gathered(texture, 0);
        for (const auto material : state_->terrain_pbr_materials)
            gatherer.add_gathered(material, 0);
    }
    {
        std::lock_guard lock(state_->region_map_image_mutex);
        gatherer.add_gathered(state_->generated_terrain_map.value_or(state_->descriptor.terrain_image), 0);
    }

    const auto parcels = state_->policies.list_parcels ? state_->policies.list_parcels()
                                                       : std::vector<std::shared_ptr<const ScriptParcel>>{};
    std::vector<std::shared_ptr<const Value>> environments;
    {
        std::lock_guard lock(state_->environment_mutex);
        if (state_->environment_day.settings)
            environments.push_back(state_->environment_day.settings);
        for (const auto &parcel : parcels) {
            if (!parcel)
                continue;
            const auto environment = state_->parcel_environment(*parcel);
            if (environment && environment->settings)
                environments.push_back(environment->settings);
        }
    }
    auto &assets = gatherer.state()->gathered;
    const auto add_textures = [&](const Value &frame, std::initializer_list<const char *> keys) {
        for (const auto *key : keys) {
            const auto id = osd_uuid(frame.get(key));
            if (!id.is_zero())
                assets[id] = 0;
        }
    };
    for (const auto &environment : environments) {
        for (const auto &[name, frame] : environment->get("day_cycle").get("frames").map) {
            const auto type = osd_string(frame.get("type"));
            if (type == "water")
                add_textures(frame, {"normal_map", "transparent_texture"});
            else if (type == "sky")
                add_textures(frame, {"bloom_id", "cloud_id", "halo_id", "moon_id", "rainbow_id", "sun_id"});
        }
    }

    if (state_->viewers) {
        std::lock_guard lock(state_->appearance_mutex);
        for (const auto &viewer : state_->viewers->agents()) {
            if (!viewer.root)
                continue;
            const auto appearance = viewer.appearance();
            if (appearance && appearance->texture)
                gather_baked_textures(gatherer, appearance->texture->faces);
        }
    }
}

std::vector<std::shared_ptr<GatherObject>> RegionRuntime::snapshot_asset_objects() const {
    std::vector<ObjectAssetPart> parts;
    {
        std::lock_guard lock(state_->task_data_mutex);
        auto objects = state_->world.objects();
        parts.reserve(objects.size());
        for (auto &object : objects) {
            auto &part = parts.emplace_back(ObjectAssetPart{std::move(object), 0, {}});
            const auto found = state_->task_parts.find(part.object.id);
            if (found == state_->task_parts.end() || !found->second.inventory)
                continue;
            for (const auto &item : found->second.inventory->items())
                part.inventory.push_back(item->clone());
        }
    }

    std::vector<ObjectAssetLinkset> objects;
    std::map<std::uint32_t, std::size_t> roots;
    std::vector<ObjectAssetPart> children;
    for (auto &part : parts) {
        if (part.object.parent_id != 0 && !part.object.is_attachment) {
            children.push_back(std::move(part));
            continue;
        }
        roots.emplace(part.object.local_id, objects.size());
        objects.emplace_back().parts.push_back(std::move(part));
    }
    for (auto &part : children) {
        const auto root = roots.find(part.object.parent_id);
        if (root != roots.end())
            objects[root->second].parts.push_back(std::move(part));
        else
            objects.emplace_back().parts.push_back(std::move(part));
    }

    std::vector<std::shared_ptr<GatherObject>> result;
    result.reserve(objects.size());
    for (auto &object : objects) {
        std::ranges::sort(object.parts.begin() + 1, object.parts.end(), {},
                          [](const auto &part) { return part.object.link_order; });
        result.push_back(gather_object_snapshot(std::move(object)));
    }
    return result;
}

ViewerRegion &RegionRuntime::viewers() {
    if (!state_->viewers)
        throw std::logic_error("Region not started");
    return *state_->viewers;
}

void RegionRuntime::load_terrain_baseline(int format, std::string_view blob) {
    if (state_->running)
        throw std::logic_error("Terrain baseline must be loaded before region startup");
    auto &terrain = state_->world.terrain();
    Terrain baseline(terrain.width(), terrain.height());
    baseline.load_database_blob(format, blob);
    state_->terrain_baseline.emplace(baseline);
}

void RegionRuntime::bake_terrain() {
    state_->bake_terrain();
}

void RegionRuntime::set_terrain_limits(float lower, float raise) {
    std::lock_guard lock(state_->terrain_edit_mutex);
    state_->terrain_lower_limit = std::clamp(lower, -200.f, 0.f);
    state_->terrain_raise_limit = std::clamp(raise, 0.f, 200.f);
}

void RegionRuntime::load_archive_creation(std::int32_t unix_seconds, std::string id) {
    std::lock_guard lock(state_->archive_creation_mutex);
    state_->archive_creation = {unix_seconds, std::move(id)};
}

void RegionRuntime::load_region_sun_settings(bool use_estate_sun) {
    std::lock_guard lock(state_->terrain_edit_mutex);
    state_->use_estate_sun = use_estate_sun;
}

bool RegionRuntime::use_estate_sun() const {
    std::lock_guard lock(state_->terrain_edit_mutex);
    return state_->use_estate_sun;
}

void RegionRuntime::load_environment_day(EnvironmentDay day) {
    if (state_->running)
        throw std::logic_error("Environment timing must be loaded before region startup");
    state_->region_environment_version = day.settings
                                             ? static_cast<std::uint32_t>(osd_integer(day.settings->get("env_version")))
                                             : std::numeric_limits<std::uint32_t>::max();
    state_->environment_day = std::move(day);
}

namespace {
class CrossingObject final : public SimulationObject {
  public:
    ObjectAssetLinkset linkset;
    std::string xml;
    std::string extra;
    bool modified = false;
    std::map<Uuid, script::LslCheckpoint> checkpoints;

    Uuid object_uuid() const override {
        return linkset.parts.front().object.id;
    }

    std::string to_xml2() override {
        return xml;
    }

    std::string extra_to_xml_string() override {
        return extra;
    }

    void extra_from_xml_string(const std::string &value) override {
        extra = value;
        auto &item = linkset.parts.front().object.from_inventory_item;
        item = {};
        constexpr std::string_view tag = "<ExtraFromItemID>";
        const auto start = value.find(tag);
        if (start != std::string::npos) {
            auto text = std::string_view(value).substr(start + tag.size());
            try_parse_sdk_uuid(text.substr(0, text.find("</ExtraFromItemID>")), item);
        }
    }

    bool has_group_changed() const override {
        return modified;
    }

    void has_group_changed(bool value) override {
        modified = value;
    }

    std::shared_ptr<SimulationObject> clone_for_new_scene() override {
        return std::make_shared<CrossingObject>(*this);
    }

    std::optional<std::string> state_snapshot() override {
        pugi::xml_document document;
        auto states = document.append_child("ScriptData").append_child("ScriptStates");
        for (const auto &part : linkset.parts) {
            for (const auto &item : part.inventory) {
                if (item.inventory_type != 10)
                    continue;
                if (const auto pending = part.managed_script_states.find(item.item_id);
                    !checkpoints.contains(item.item_id) && pending != part.managed_script_states.end() &&
                    !pending->second.original_xml.empty()) {
                    pugi::xml_document retained;
                    if (retained.load_buffer(pending->second.original_xml.data(),
                                             pending->second.original_xml.size()) &&
                        std::string_view(retained.document_element().name()) == "ScriptState") {
                        auto state = states.append_child("State");
                        state.append_attribute("Engine") = "YEngine";
                        state.append_attribute("UUID") = item.item_id.str().c_str();
                        state.append_attribute("Asset") = item.asset_id.str().c_str();
                        state.append_copy(retained.document_element());
                        continue;
                    }
                }
                auto state = states.append_child("State");
                state.append_attribute("Engine") = "NativeLSL";
                state.append_attribute("UUID") = item.item_id.str().c_str();
                state.append_attribute("Asset") = item.asset_id.str().c_str();
                auto script_state = state.append_child("ScriptState");
                script_state.append_child("Running").text().set(item.script_running ? "True" : "False");
                if (const auto checkpoint = checkpoints.find(item.item_id); checkpoint != checkpoints.end()) {
                    const auto bytes = std::make_shared<std::vector<std::uint8_t>>(
                        script::encode_persistent_lsl_checkpoint(checkpoint->second, false));
                    const auto encoded = binary_base64(osd_from_binary(bytes));
                    script_state.append_child("NativeCheckpoint").text().set(encoded.c_str());
                    if (!checkpoint->second.listeners.empty()) {
                        try {
                            const auto listener_bytes = std::make_shared<std::vector<std::uint8_t>>(
                                script::encode_lsl_listeners(checkpoint->second.listeners));
                            const auto listeners = binary_base64(osd_from_binary(listener_bytes));
                            script_state.append_child("NativeListeners").text().set(listeners.c_str());
                        } catch (const std::length_error &) {
                            // Keep the VM checkpoint even if the listener extension exceeds the wire limit.
                        }
                    }
                }
            }
        }
        if (!states.first_child())
            return std::string{};
        std::ostringstream output;
        document.save(output, "", pugi::format_raw | pugi::format_no_declaration);
        return output.str();
    }

    void set_state(const std::optional<std::string> &xml_state, AgentTransferScene *) override {
        if (!xml_state)
            return;
        pugi::xml_document document;
        if (!document.load_buffer(xml_state->data(), xml_state->size()))
            return;
        for (const auto state : document.child("ScriptData").child("ScriptStates").children("State")) {
            Uuid item_id, asset_id;
            if (!try_parse_sdk_uuid(state.attribute("UUID").value(), item_id) || item_id.is_zero() ||
                !try_parse_sdk_uuid(state.attribute("Asset").value(), asset_id) || asset_id.is_zero())
                continue;
            const auto script_state = state.child("ScriptState");
            const std::string_view running = script_state.child_value("Running");
            const bool stopped = running == "False" || running == "false" || running == "0";
            if (!stopped && running != "True" && running != "true" && running != "1")
                continue;

            const std::string_view engine = state.attribute("Engine").value();
            for (auto &part : linkset.parts) {
                for (auto &item : part.inventory) {
                    if (item.inventory_type != 10 || item.item_id != item_id || item.asset_id != asset_id)
                        continue;

                    checkpoints.erase(item_id);
                    if (engine == "YEngine") {
                        auto saved = read_managed_script_state(script_state);
                        if (saved.source_hash.empty())
                            item.script_running = !stopped;
                        part.managed_script_states.insert_or_assign(item_id, std::move(saved));
                        continue;
                    }

                    item.script_running = !stopped;
                    if (engine == "NativeLSL")
                        restore_native_checkpoint(item, script_state);
                }
            }
        }
    }

  private:
    void restore_native_checkpoint(const TaskInventoryItem &item, pugi::xml_node script_state) {
        const std::string_view encoded = script_state.child_value("NativeCheckpoint");
        if (encoded.empty())
            return;

        Value binary;
        binary.kind = Value::Kind::Binary;
        binary.text = encoded;
        try {
            auto saved = script::decode_lsl_checkpoint(*osd_binary(binary));
            if (!saved || saved->running != item.script_running)
                return;
            auto &checkpoint = checkpoints.insert_or_assign(item.item_id, std::move(*saved)).first->second;

            const std::string_view listeners = script_state.child_value("NativeListeners");
            if (listeners.empty())
                return;
            Value listener_data;
            listener_data.kind = Value::Kind::Binary;
            listener_data.text = listeners;
            if (auto decoded = script::decode_lsl_listeners(*osd_binary(listener_data)))
                checkpoint.listeners = std::move(*decoded);
        } catch (const std::exception &) {
            // A malformed listener extension leaves the accepted VM checkpoint intact.
        }
    }
};

class CrossingScene final : public AgentTransferScene {
    bool allow_scripts_;

  public:
    explicit CrossingScene(bool allow_scripts) : allow_scripts_(allow_scripts) {}

    bool allow_script_crossings() const override {
        return allow_scripts_;
    }

    std::shared_ptr<AgentTransferObject> deserialize_object(const std::string &xml) override {
        auto asset = read_object_asset_xml({reinterpret_cast<const std::uint8_t *>(xml.data()), xml.size()});
        if (!asset || asset->coalesced || asset->linksets.size() != 1 || asset->linksets.front().parts.empty())
            return {};
        auto object = std::make_shared<CrossingObject>();
        object->xml = xml;
        object->linkset = std::move(asset->linksets.front());
        return object;
    }
};
} // namespace

bool RegionRuntime::State::start_object_crossing(const SceneObject &root, Vector3 position) {
    if (root.parent_id || root.is_attachment)
        return false;
    const bool inside =
        position.x >= 0 && position.x < descriptor.size_x && position.y >= 0 && position.y < descriptor.size_y;
    if (root.die_at_edge && !inside) {
        world.remove(root.id);
        return true;
    }
    if (root.return_at_edge && !inside) {
        std::lock_guard lock(commands_mutex);
        edge_return_requests.insert(root.id);
        return true;
    }
    if (!policies.send_crossing_object || !policies.teleport_destination)
        return false;
    std::lock_guard lock(object_crossings_mutex);
    if (object_crossings.contains(root.id))
        return true;
    if (inside)
        return false;
    if (running && world.object(root.id)) {
        queued_object_crossings.push_back({root, position, {}});
        object_crossings.try_emplace(root.id, root.local_id);
    }
    return true;
}

std::future<std::optional<RegionRuntime::State::ObjectCrossingArrival>>
RegionRuntime::State::launch_object_crossing(const SceneObject &root, Vector3 position,
                                             std::optional<ObjectTeleportCrossing> teleport) {
    const auto current = world.object(root.id);
    if (!current || current->local_id != root.local_id)
        return {};
    auto riders = linkset_sitters(root.id);
    std::vector<bool> rider_in_transit;
    rider_in_transit.reserve(riders.size());
    for (const auto &rider : riders)
        rider_in_transit.push_back(!rider.npc_owner && agent_transfer_pending(rider.circuit->session_id));
    return std::async(
        std::launch::async,
        [this, root_id = root.id, root_local_id = root.local_id, lookup = policies.teleport_destination,
         send = policies.send_crossing_object, access = policies.teleport_access, riders = std::move(riders),
         rider_in_transit = std::move(rider_in_transit), source_x = descriptor.x, source_y = descriptor.y, position,
         teleport]() -> std::optional<ObjectCrossingArrival> {
            Vector3 local;
            auto destination = object_crossing_destination(
                true, source_x, source_y, position,
                [&](std::int32_t x, std::int32_t y) {
                    const auto handle =
                        (std::uint64_t(std::bit_cast<std::uint32_t>(x)) << 32) | std::bit_cast<std::uint32_t>(y);
                    return lookup(handle);
                },
                local);
            if (!destination)
                return std::nullopt;
            // CrossAsync refuses the entire linkset before CreateObject if a
            // non-NPC sitter is already transferring or cannot enter the region.
            auto context = std::make_shared<LoginTransferContext>();
            for (std::size_t index = 0; index < riders.size(); ++index) {
                const auto &rider = riders[index];
                if (rider.npc_owner)
                    continue;
                if (rider_in_transit[index] || !access)
                    return std::nullopt;
                const auto agent = rider.circuit->agent_id;
                if (crossing_bans.if_banned(destination->handle(), agent))
                    return std::nullopt;
                if (!access(*destination, rider, local, false, *context).empty()) {
                    crossing_bans.add(destination->handle(), agent, 60.);
                    return std::nullopt;
                }
                const auto appearance =
                    rider.appearance_override ? rider.appearance_override : rider.circuit->appearance;
                if (appearance && !appearance->can_teleport(context->outbound_version)) {
                    crossing_bans.add(destination->handle(), agent, 60.);
                    return std::nullopt;
                }
            }
            // Original CrossAsync applies teleport motion only in its seated
            // branch. An unseated teleport sends the existing motion unchanged.
            auto transfer = request_crossing_snapshot(
                root_id, root_local_id, teleport && !riders.empty() ? std::optional{teleport->motion} : std::nullopt);
            if (!transfer || !send(*destination, local, transfer))
                return std::nullopt;
            return ObjectCrossingArrival{std::move(*destination), local, std::move(context),
                                         !teleport || !riders.empty(), teleport.has_value()};
        });
}

std::shared_ptr<CrossingObject> RegionRuntime::State::snapshot_crossing_object(const SceneObject &root) {
    std::lock_guard motion_lock(task_data_mutex);
    auto transfer = std::make_shared<CrossingObject>();
    auto &parts = transfer->linkset.parts;
    parts.push_back({root});
    std::optional<std::vector<std::uint8_t>> attachment_xml_motion;
    if (root.is_attachment) {
        // CopyAttachments clones the component before setting the detached
        // clone's GroupPosition to AttachedPos. Typed transfers carry Copy's
        // state; remote XML performs a later Serialize at the detached offset.
        auto &detached = parts.front().object;
        detached.is_attachment = false;
        detached.attached_group_position = root.position;
        detached.keyframed_motion.clear();
        if (const auto source = keyframed_motions.find(root.id);
            source != keyframed_motions.end() && source->second->expected.local_id == root.local_id) {
            KeyframedMotionHost host;
            host.position = [offset = root.position] { return offset; };
            auto copied = source->second->motion->copy(std::move(host));
            const auto &state = copied->state();
            detached.keyframed_motion = encode_keyframed_motion(
                {state, state.frame_backing, state.frame_list_version, state.keyframes_share_backing});
            attachment_xml_motion = copied->serialize();
        }
    } else {
        capture_keyframed_motion(parts.front().object);
    }
    for (const auto &part : world.objects())
        if (!part.is_attachment && part.parent_id == root.local_id)
            parts.push_back({part});
    std::ranges::sort(std::span(parts).subspan(1), {}, [](const auto &part) { return part.object.link_order; });
    for (auto &part : parts) {
        part.attachment_position =
            root.is_attachment && part.object.id == root.id ? root.position : part.object.saved_attachment_position;
        part.last_attachment_point = part.object.last_attachment_point;
    }
    {
        std::lock_guard lock(task_data_mutex);
        for (auto &part : parts) {
            const auto found = task_parts.find(part.object.id);
            if (found == task_parts.end() || !found->second.inventory)
                continue;
            part.inventory_serial = found->second.inventory->serial();
            capture_pending_managed_states(part);
            for (const auto &item : found->second.inventory->items()) {
                part.inventory.push_back(*item);
                if (auto checkpoint = snapshot_script_checkpoint(part.object.id, item->item_id)) {
                    part.inventory.back().script_running = checkpoint->running;
                    transfer->checkpoints.emplace(item->item_id, std::move(*checkpoint));
                }
            }
        }
    }
    std::u16string xml;
    XmlTextWriterIo io;
    io.encoding = [] { return std::shared_ptr<NativeXmlTextEncoding>{}; };
    io.write = [&](auto, auto text) {
        if (text)
            xml.append(*text);
    };
    io.write_array = [&](auto data, int offset, int count) { xml.append(data->data() + offset, count); };
    io.write_whole_array = [&](auto data) { xml.append(data->data(), data->size()); };
    NativeXmlTextWriter writer(std::move(io));
    auto xml_root = parts.front();
    if (attachment_xml_motion)
        xml_root.object.keyframed_motion = std::move(*attachment_xml_motion);
    write_crossing_object_xml(writer, xml_root, std::span(parts).subspan(1));
    transfer->xml = utf8(xml);
    transfer->modified = root.changed;
    transfer->extra = "<ExtraFromItemID>" + root.from_inventory_item.str() + "</ExtraFromItemID>";
    return transfer;
}

std::shared_ptr<AgentTransferScene> RegionRuntime::get_scene(const Uuid &region) {
    if (!state_->running || region != state_->descriptor.id)
        return {};
    return std::make_shared<CrossingScene>(state_->policies.allow_script_crossing);
}

bool RegionRuntime::create_object(GridRegion *destination, const Vector3 &position,
                                  std::shared_ptr<SimulationObject> object, bool local_call) {
    auto &state = *state_;
    auto transfer = std::dynamic_pointer_cast<CrossingObject>(object);
    if (!destination || !transfer || transfer->linkset.parts.empty() || destination->id != state.descriptor.id ||
        !state.running)
        return false;
    auto &root = transfer->linkset.parts.front().object;
    if (root.owner.is_zero())
        return false;
    const bool administrator = state.god_rights_level(root.owner) >= 200;
    std::string reason;
    if (!administrator && state.deny_estate_ban(root.owner, reason))
        return false;
    if (root.is_attachment || (root.shape.pcode == 9 && root.shape.state != 0)) {
        if (!state.policies.attachments_enabled || !state.viewers ||
            std::ranges::any_of(transfer->linkset.parts,
                                [&](const auto &part) { return part.object.owner != root.owner; }))
            return false;
        std::lock_guard lock(state.new_mutex);
        const auto wearer = state.viewers->agent(root.owner);
        if (wearer && wearer->logout_requested)
            return false;
        if (!wearer || !wearer->root) {
            if (state.world.object(root.id))
                return false;
            const auto reserved = state.circuits.get_agent_circuit_data(root.owner);
            const bool matching_reservation =
                reserved && (!wearer || reserved->session_id == wearer->circuit->session_id);
            const auto circuit = matching_reservation ? reserved : (wearer ? wearer->circuit : nullptr);
            if (!circuit)
                return false;
            auto &pending = state.incoming_object_attachments[std::weak_ptr{circuit}];
            if (std::ranges::any_of(pending, [&](const auto &entry) { return entry->object_uuid() == root.id; }))
                return true;
            pending.push_back(std::make_shared<CrossingObject>(*transfer));
            return true;
        }
        return state.attach_crossing_object(*wearer, *transfer, 256);
    }
    const auto point = position != Vector3{} ? position : root.position;
    if (!std::isfinite(point.x) || !std::isfinite(point.y) || !std::isfinite(point.z))
        return false;
    if (!state.object_can_enter(root, point, true, static_cast<std::int32_t>(transfer->linkset.parts.size())))
        return false;

    const auto root_id = root.id;
    // In-process transfers already carry typed script checkpoints and listener state.
    if (local_call)
        transfer = std::make_shared<CrossingObject>(*transfer);

    std::vector<SceneObject> parts;
    parts.reserve(transfer->linkset.parts.size());
    for (const auto &part : transfer->linkset.parts)
        parts.push_back(part.object);
    parts.front().position = point;
    if (!state.world.add_crossing_linkset(std::move(parts)))
        return false;
    constexpr std::int32_t changed_region = 256;
    state.restore_crossing_inventory(*transfer, changed_region);
    state.world.publish_added_linkset(root_id);
    return true;
}

void RegionRuntime::State::rez_npc_attachments(const ViewerAgent &npc) {
    const auto appearance = npc.appearance();
    if (!policies.attachments_enabled || !policies.load_asset || !appearance)
        return;

    const auto agent = npc.circuit->agent_id;
    for (const auto &attachment : appearance->attachments()) {
        if (attachment.asset.is_zero() || attachment.point < 0 || attachment.point > 55)
            continue;
        try {
            const auto asset = policies.load_asset(attachment.asset);
            if (!asset || !asset->data)
                continue;
            auto decoded = read_object_asset_xml(*asset->data);
            if (!decoded || decoded->coalesced || decoded->linksets.size() != 1)
                continue;

            CrossingObject transfer;
            transfer.linkset = std::move(decoded->linksets.front());
            auto &parts = transfer.linkset.parts;
            if (parts.empty())
                continue;
            auto &root = parts.front();
            auto point = static_cast<std::uint8_t>(attachment.point);
            auto offset = root.object.position;
            if (point && point != root.object.shape.state)
                offset = {};
            if (point && point == root.last_attachment_point)
                offset = root.attachment_position;
            if (!point)
                point = root.object.shape.state;
            if (!point) {
                point = root.last_attachment_point;
                offset = root.attachment_position;
            }
            if (!point) {
                point = 5;
                offset = {};
            }
            if (point > 55)
                continue;
            const auto motion_admission_position = root.object.attached_group_position.value_or(root.object.position);
            root.object.position = offset;
            root.object.attached_group_position = offset;
            root.object.shape.state = point;
            root.object.from_inventory_item = Uuid::random();
            root.object.from_inventory_folder = {};
            root.object.attachment_source_asset = attachment.asset;

            std::vector<SceneObject> objects;
            objects.reserve(parts.size());
            for (auto &part : parts) {
                auto &object = part.object;
                object.id = Uuid::random();
                object.is_attachment = false;
                if (object.owner != agent && object.owner != object.group)
                    object.last_owner = object.owner;
                object.owner = object.rezzer = agent;
                object.group = npc.active_group_id();
                object.changed = false;
                for (auto &item : part.inventory) {
                    const auto previous = item.item_id;
                    item.reset_ids(object.id);
                    if (item.owner_id != agent) {
                        item.last_owner_id = item.owner_id;
                        item.owner_id = agent;
                        item.owner_changed = true;
                    }
                    item.group_id = object.group;
                    item.permissions_granter = {};
                    item.permissions_mask = 0;
                    if (auto state = part.managed_script_states.extract(previous); !state.empty()) {
                        state.key() = item.item_id;
                        part.managed_script_states.insert(std::move(state));
                    }
                    if (const auto state = part.native_script_checkpoints.find(previous);
                        state != part.native_script_checkpoints.end()) {
                        item.script_running = state->second.running;
                        transfer.checkpoints.emplace(item.item_id, std::move(state->second));
                    }
                }
                objects.push_back(object);
            }
            if (!world.add_crossing_linkset(std::move(objects), npc.local_id))
                continue;
            restore_keyframed_motions(std::pair{root.object.id, motion_admission_position});
            if (const auto attached = world.object(root.object.id))
                set_group_selected(*attached, false);
            restore_crossing_inventory(transfer, 0, agent);
            world.publish_added_linkset(root.object.id);
        } catch (const std::exception &failure) {
            error("Could not rez NPC attachment " + attachment.asset.str() + ": " + failure.what());
        }
    }
}

void RegionRuntime::State::restore_crossing_inventory(const CrossingObject &transfer, std::int32_t changed,
                                                      Uuid attached_avatar) {
    std::lock_guard lock(task_data_mutex);
    for (const auto &part : transfer.linkset.parts) {
        if (part.inventory.empty() && part.inventory_serial == 0)
            continue;
        std::vector<TaskInventoryRegistry::Item> inventory;
        for (const auto &item : part.inventory)
            inventory.push_back(std::make_shared<TaskInventoryItem>(item));
        auto &registry = task_inventory(part.object.id);
        registry.restore(inventory);
        registry.serial(part.inventory_serial);
        for (const auto &item : inventory) {
            if (item->inventory_type != 10)
                continue;
            const auto script_key = std::pair{part.object.id, item->item_id};
            const auto plugins = part.managed_script_states.find(item->item_id);
            if (plugins != part.managed_script_states.end())
                incoming_managed_script_states.insert_or_assign(script_key, plugins->second);
            const auto checkpoint = transfer.checkpoints.find(item->item_id);
            if (checkpoint != transfer.checkpoints.end())
                incoming_script_checkpoints.insert_or_assign(script_key, checkpoint->second);
            restored_scripts.push_back({part.object.id, item->item_id, changed, attached_avatar});
        }
    }
}

void RegionRuntime::snapshot_attachments(const ViewerAgent &avatar, AgentData &data) {
    state_->snapshot_attachments(avatar, data);
}

void RegionRuntime::State::snapshot_attachments(const ViewerAgent &avatar, AgentData &data) {
    data.cached_friends_online.reset();
    if (policies.friends_online_cache) {
        if (const auto online = policies.friends_online_cache->get(avatar.circuit->agent_id)) {
            data.cached_friends_online = std::make_shared<framework::TransferList<Uuid>>();
            for (const auto id : *online)
                data.cached_friends_online->push_back(id);
        }
    }
    std::lock_guard lock(task_data_mutex);
    const auto input = viewer_script_controls.find(avatar.circuit->session_id);
    const auto effective_controls =
        input == viewer_script_controls.end() ? avatar.controls : input->second.movement.value_or(avatar.controls);
    data.control_flags = effective_controls | (avatar.flying ? 0x2000u : 0u);
    const auto animations = avatar_script_animations.find(avatar.circuit->agent_id);
    const auto physics = viewer_physics.load();
    if (!avatar.seat && !avatar.ground_sitting && physics) {
        if (const auto movement = physics->movement_animation(avatar.circuit->agent_id, avatar.circuit->session_id)) {
            const auto copy = [](const std::optional<AvatarAnimationEntry> &animation) {
                return animation ? std::make_shared<Animation>(animation->animation, animation->sequence, Uuid{})
                                 : nullptr;
            };
            data.default_animation = copy(movement->current);
            data.animation_state = copy(movement->implicit);
            data.motion_state = static_cast<std::uint8_t>(movement->phase);
            if (std::getenv("OPENSIM_TRACE_AGENT_DATA"))
                error("TRANSFER_ANIMATION_SNAPSHOT agent=" + avatar.circuit->agent_id.str() + " current=" +
                      (data.default_animation ? data.default_animation->animation_id.str() : "none") + " sequence=" +
                      std::to_string(data.default_animation ? data.default_animation->sequence_number : 0) +
                      " phase=" + std::to_string(data.motion_state));
        }
    } else {
        const bool current =
            animations != avatar_script_animations.end() && animations->second.session == avatar.circuit->session_id;
        const auto sequence = current ? animations->second.default_sequence : 1;
        const auto animation = default_avatar_animation(avatar.circuit->agent_id);
        data.default_animation = std::make_shared<Animation>(animation, sequence, Uuid{});
        if (current)
            data.animation_state = animations->second.transferred_implicit;
        if (!data.animation_state && !animation.is_zero())
            data.animation_state = data.default_animation;
    }
    if (animations != avatar_script_animations.end() && animations->second.session == avatar.circuit->session_id) {
        if (!animations->second.entries.empty()) {
            data.animations = std::make_shared<std::vector<std::shared_ptr<Animation>>>();
            for (const auto &entry : animations->second.entries)
                data.animations->push_back(std::make_shared<Animation>(entry.animation, entry.sequence, entry.object));
        }
        for (const auto &[label, state] : movement_animation_names) {
            const auto override = animations->second.overrides.find(movement_state_animation(state));
            if (override != animations->second.overrides.end())
                (*data.movement_animation_overrides)[std::string(state)] = override->second;
        }
    }
    if (input != viewer_script_controls.end()) {
        if (input->second.previous & left_button_down)
            data.cross_extra_flags |= crossing_left_button;
        if (input->second.previous & mouselook_button_down)
            data.cross_extra_flags |= crossing_mouselook_button;
    }
    if (policies.attachments_enabled) {
        for (const auto &attachment : world.attachments(avatar.local_id)) {
            if (attachment.owner != avatar.circuit->agent_id)
                continue;
            auto transfer = snapshot_crossing_object(attachment);
            if (!data.attachment_objects) {
                data.attachment_objects = std::make_shared<TransferList<std::shared_ptr<AgentTransferObject>>>();
                data.attachment_object_states = std::make_shared<TransferList<std::optional<std::string>>>();
            }
            data.attachment_object_states->push_back(transfer->state_snapshot());
            data.attachment_objects->push_back(std::move(transfer));
        }
    }
    for (const auto &[item, controls] : captured_controls) {
        if (controls.avatar != avatar.circuit->agent_id || controls.session != avatar.circuit->session_id)
            continue;
        const auto script = scripts.find(item);
        if (script == scripts.end())
            continue;
        const auto root = world.link_key(script->second.item.parent, 1);
        if (root.is_zero())
            continue;
        if (!data.controllers)
            data.controllers = std::make_shared<std::vector<std::shared_ptr<ControllerData>>>();
        data.controllers->push_back(std::make_shared<ControllerData>(root, item, controls.ignored, controls.events));
    }
}

void RegionRuntime::State::restore_crossing_attachments(const ViewerAgent &avatar, AgentData &data) {
    CrossingScene scene(policies.allow_script_crossing);
    constexpr std::int32_t changed_region = 256, changed_teleport = 512;
    const auto changed = avatar.circuit->teleport_flags == 0 ? changed_region : changed_region | changed_teleport;
    for (std::size_t index = 0; index < data.attachment_objects->size(); ++index) {
        const auto transfer = std::dynamic_pointer_cast<CrossingObject>(data.attachment_objects->get(index));
        if (!transfer || transfer->linkset.parts.empty())
            continue;
        if (std::ranges::any_of(transfer->linkset.parts,
                                [&](const auto &part) { return part.object.owner != avatar.circuit->agent_id; }))
            continue;
        if (policies.allow_script_crossing && data.attachment_object_states &&
            index < data.attachment_object_states->size())
            transfer->set_state(data.attachment_object_states->get(index), &scene);
        attach_crossing_object(avatar, *transfer, changed);
    }
}

bool RegionRuntime::State::attach_crossing_object(const ViewerAgent &avatar, const CrossingObject &transfer,
                                                  std::int32_t changed) {
    std::lock_guard lock(new_mutex);
    const auto current = viewers->agent(avatar.circuit->agent_id);
    if (!current || !current->root || current->logout_requested || current->circuit != avatar.circuit ||
        current->local_id != avatar.local_id)
        return false;
    const auto &root = transfer.linkset.parts.front().object;
    if (const auto existing = world.object(root.id))
        return existing->is_attachment && existing->owner == root.owner && existing->parent_id == avatar.local_id;

    std::vector<SceneObject> parts;
    parts.reserve(transfer.linkset.parts.size());
    for (const auto &part : transfer.linkset.parts)
        parts.push_back(part.object);
    parts.front().changed = transfer.modified;
    if (!world.add_crossing_linkset(std::move(parts), avatar.local_id))
        return false;
    restore_keyframed_motions(std::pair{root.id, root.attached_group_position.value_or(root.position)});
    if (const auto attached = world.object(root.id))
        set_group_selected(*attached, false);
    restore_crossing_inventory(transfer, changed);
    world.publish_added_linkset(transfer.object_uuid());
    return true;
}

void RegionRuntime::restore_task_inventory(Uuid part,
                                           const std::vector<std::shared_ptr<framework::TaskInventoryItem>> &items,
                                           const TaskScriptStates &script_states, TaskInventoryRestoreSource source) {
    if (items.empty() || !state_->world.object(part))
        return;
    std::lock_guard lock(state_->task_data_mutex);
    auto &inventory = state_->task_inventory(part);
    inventory.restore(items);
    for (const auto &item : items) {
        if (!item || item->inventory_type != 10 || inventory.find(item->item_id) != item)
            continue;
        bool has_native_checkpoint = false;
        if (const auto saved = script_states.find(item->item_id); saved != script_states.end()) {
            if (auto checkpoint = script::decode_lsl_checkpoint(saved->second)) {
                has_native_checkpoint = true;
                item->script_running = checkpoint->running;
                state_->incoming_script_checkpoints.insert_or_assign({part, item->item_id}, std::move(*checkpoint));
            } else if (auto managed = read_yengine_state_xml(saved->second, item->asset_id)) {
                has_native_checkpoint =
                    true; // An opaque original state also takes precedence over a filesystem fallback.
                item->script_running = managed->running.value_or(item->script_running);
                state_->incoming_managed_script_states.insert_or_assign({part, item->item_id}, std::move(*managed));
            }
        }
        if (source == TaskInventoryRestoreSource::RegionStart && !has_native_checkpoint &&
            !state_->policies.yengine_state_root.empty()) {
            const auto directory = state_->policies.yengine_state_root / "Yengine" / state_->descriptor.id.str();
            if (auto saved = read_yengine_state_file(directory, item->item_id, item->asset_id))
                state_->incoming_managed_script_states.insert_or_assign({part, item->item_id}, std::move(*saved));
        }
        state_->restored_scripts.push_back(
            {part, item->item_id, source == TaskInventoryRestoreSource::RegionStart ? State::changed_region_start : 0});
    }
}

RegionRuntime::TaskScriptStates RegionRuntime::snapshot_task_script_states(Uuid part) const {
    std::lock_guard lock(state_->task_data_mutex);
    TaskScriptStates result;
    const auto found = state_->task_parts.find(part);
    if (found == state_->task_parts.end() || !found->second.inventory)
        return result;
    for (const auto &item : found->second.inventory->items()) {
        if (item->inventory_type != 10)
            continue;
        if (const auto pending = state_->incoming_managed_script_states.find({part, item->item_id});
            pending != state_->incoming_managed_script_states.end() && !pending->second.original_xml.empty()) {
            const auto projected = state_->project_managed_admission_events(part, item->item_id, pending->second);
            const auto &xml = projected.original_xml;
            result.emplace(item->item_id, std::vector<std::uint8_t>(xml.begin(), xml.end()));
            continue;
        }
        if (auto checkpoint = state_->snapshot_script_checkpoint(part, item->item_id)) {
            if (!state_->incoming_script_checkpoints.contains({part, item->item_id})) {
                checkpoint->permissions_granter = item->permissions_granter;
                checkpoint->permissions_mask = item->permissions_mask;
            }
            try {
                result.emplace(item->item_id, script::encode_persistent_lsl_checkpoint(*checkpoint));
            } catch (const std::length_error &) {
                state_->error("Script checkpoint exceeds the persistence limit for " + item->item_id.str());
            }
        }
    }
    return result;
}

std::optional<std::vector<framework::TaskInventoryItem>> RegionRuntime::snapshot_task_inventory(Uuid part) const {
    std::lock_guard lock(state_->task_data_mutex);
    const auto found = state_->task_parts.find(part);
    if (found == state_->task_parts.end() || !found->second.inventory)
        return std::nullopt;
    std::vector<framework::TaskInventoryItem> result;
    for (const auto &item : found->second.inventory->items())
        result.push_back(*item);
    return result;
}

std::string RegionRuntime::wind_console_command(std::span<const std::string> arguments) {
    if (arguments.size() < 3 || arguments.size() > 4)
        return "Usage: wind <plugin> <param> [value]";
    auto &state = *state_;
    std::lock_guard lock(state.wind_config_mutex);
    auto &wind = state.policies.wind;
    const auto &plugin = arguments[1];
    const auto &parameter = arguments[2];
    if (plugin == "base" && parameter == "wind_update_rate") {
        if (arguments.size() != 4)
            return "Invalid parameters to change parameters for Wind module base, usage: wind base <parameter> <value>";
        unsigned int frames = 0;
        const auto &input = arguments[3];
        if (!framework::try_parse_unsigned_integer(input, frames) || frames == 0 ||
            frames > static_cast<unsigned int>(std::numeric_limits<int>::max()))
            return "Invalid value " + input + " specified for " + parameter;
        wind.update_frames = static_cast<int>(frames);
        return {};
    }
    auto *value = wind_parameter(wind, plugin, parameter);
    if (!value)
        return "Unknown " + plugin + " parameter " + parameter;
    std::string output;
    if (arguments.size() == 4) {
        float parsed = 0.f;
        if (!framework::parse_invariant_float(arguments[3], parsed)) {
            output = "Invalid value " + arguments[3] + "\n";
            parsed = 0.f;
        }
        *value = parsed;
    }
    std::ostringstream formatted;
    formatted << *value;
    return output + parameter + (arguments.size() == 4 ? " set to " : " : ") + formatted.str();
}

void RegionRuntime::set_scripts_enabled(bool enabled) {
    std::lock_guard lock(state_->estate_region_settings_mutex);
    constexpr std::uint32_t skip_scripts = 0x2000u;
    if (enabled)
        state_->region_setting_flags.fetch_and(~skip_scripts);
    else
        state_->region_setting_flags.fetch_or(skip_scripts);
}

